import re, sys, zlib
data = open(sys.argv[1], 'rb').read()
objs = {int(m.group(1)): m.group(2) for m in re.finditer(rb'(\d+) 0 obj(.*?)endobj', data, re.S)}

def stream(b):
    m = re.search(rb'stream\r?\n(.*?)endstream', b, re.S)
    if not m:
        return None
    try:
        return zlib.decompress(m.group(1))
    except Exception:
        return None

def parse_cmap(s):
    cm = {}
    for blk in re.findall(rb'beginbfchar(.*?)endbfchar', s, re.S):
        for a, b in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
            cm[int(a, 16)] = bytes.fromhex(b.decode()).decode('utf-16-be', 'replace')
    for blk in re.findall(rb'beginbfrange(.*?)endbfrange', s, re.S):
        for a, b, c in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
            for i in range(int(a, 16), int(b, 16) + 1):
                cm[i] = chr(int(c, 16) + i - int(a, 16))
    return cm

font_cmap = {}
for n, b in objs.items():
    m = re.search(rb'/ToUnicode (\d+) 0 R', b)
    if m and int(m.group(1)) in objs:
        s = stream(objs[int(m.group(1))])
        if s:
            font_cmap[n] = parse_cmap(s)

names = {}
for b in objs.values():
    for fm in re.finditer(rb'/Font\s*<<(.*?)>>', b, re.S):
        for name, ref in re.findall(rb'/(F\d+) (\d+) 0 R', fm.group(1)):
            names[name] = int(ref)

out = []
for n in sorted(objs):
    s = stream(objs[n])
    if not s or b'BT' not in s or b'Tf' not in s:
        continue
    cur, last_tm = {}, None
    for t in re.finditer(rb'/(F\d+) [\d.]+ Tf|([-\d. ]+) Tm|<([0-9A-Fa-f]+)>\s*Tj', s):
        if t.group(1):
            cur = font_cmap.get(names.get(t.group(1)), {})
        elif t.group(2):
            if t.group(2) != last_tm:
                out.append('\n')
                last_tm = t.group(2)
        else:
            h = t.group(3).decode()
            out.append(''.join(cur.get(int(h[i:i+4], 16), '?') for i in range(0, len(h), 4)))
    out.append('\n=== page break ===\n')
print(''.join(out))
EOF
