COPY nginx.conf /etc/nginx/conf.d/default.conf
COPY --from=build /app/dist /usr/share/nginx/html

EXPOSE 80
EOF
cat > frontend/.dockerignore <<'EOF'
node_modules/
dist/
.env
Dockerfile
.dockerignore
EOF
cat > e2e/package.json <<'EOF'
{
  "name": "job-dashboard-e2e",
  "private": true,
  "version": "0.1.0",
  "scripts": {
    "test": "playwright test"
  },
  "devDependencies": {
    "@playwright/test": "1.64.0",
    "@types/node": "22.19.1"
  }
}
EOF
npm view @types/node@22 version 2>/dev/null | tail -1
cat > e2e/playwright.config.ts <<'EOF'
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests',
  // Fail the run if a stray `test.only` is committed.
  forbidOnly: true,
  // One retry absorbs a transient infrastructure hiccup; a test that needed it
  // is reported as "flaky" instead of silently passing.
  retries: 1,
  reporter: 'list',
  use: {
    // Inside the compose network the app is reached by its service name.
    baseURL: process.env.BASE_URL ?? 'http://frontend',
    trace: 'retain-on-failure',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
});
EOF
cat > e2e/tests/smoke.spec.ts <<'EOF'
import { expect, test } from '@playwright/test';

// Walks the whole chain: browser -> nginx -> gunicorn/Django -> Postgres.
test('page loads through nginx and the backend reports healthy', async ({ page }) => {
  await page.goto('/');

  await expect(page.getByRole('heading', { name: 'Job Management Dashboard' })).toBeVisible();
  await expect(page.getByRole('status')).toHaveText('Backend: healthy');
});
EOF
cat > e2e/Dockerfile <<'EOF'
# Built from a Docker Hub image on purpose: the official Playwright image is
# hosted on mcr.microsoft.com, which the brief does not promise is reachable.
FROM node:22-bookworm-slim

WORKDIR /e2e

COPY package.json package-lock.json ./
RUN npm ci

# Installs the headless Chromium build plus the system libraries it needs.
# The browser version is tied to the pinned @playwright/test version.
RUN npx playwright install --with-deps --only-shell chromium

COPY . .

CMD ["npx", "playwright", "test"]
EOF
cat > e2e/.dockerignore <<'EOF'
node_modules/
test-results/
playwright-report/
Dockerfile
.dockerignore
EOF

